AM,SAzFD,CA0FL,KAAM,oBA1FD,CA2FL,KAAM,OA3FD,CA4FL,KAAM,OA5FD,CA6FL,KAAM,QA7FD,CA8FL,KAAM,MA9FD,CA+FL,KAAM,SA/FD,CAgGL,KAAM,WAhGD,CAiGL,KAAM,MAjGD,CAkGL,KAAM,OAlGD,CAmGL,KAAM,YAnGD,CAoGL,KAAM,OApGD,CAqGL,KAAM,OArGD,CAsGL,KAAM,SAtGD,CAuGL,KAAM,QAvGD,CAwGL,KAAM,MAxGD,CADc,CA2GrBC,YAAY3B,IAAZ,CAAkB4B,IAAlB,CAAwB,CACtB,GAAG,CAACH,IAAIC,KAAJ,CAAUE,IAAV,CAAD,EAAoB5B,KAAK7E,MAAL,EAAe,GAAtC,CAA2C,CACzC,MACD,CACD,KAAM0G,IAAKC,KAAKC,KAAL,CAAWD,KAAKE,MAAL,GAAgB,OAA3B,CAAX,CACA,KAAMC,KAAO,0DAAyDL,IAAK,mBAAkBM,mBAAmBlC,IAAnB,CAAyB,OAAM6B,EAAG,aAA/H,CACA,MAAO,iDAAmDK,mBAAmBD,GAAnB,CAA1D,CAEA;AACD,CApHoB,CAAvB,CAuHA;AACA;AACA;AAEA;;;;;;;GAQA,GAAIE,UAAW3H,OAAO2H,QAAP,CAAkB,SAASC,OAAT,CAAkBC,QAAlB,CAA4BC,QAA5B,CAAsC,CACrE,GAAIC,GAAIlG,SAASmG,aAAT,CAAuB,GAAvB,CAAR,CACAF,SAAWA,UAAY,0BAAvB,CAEA;AACA,GAAGG,UAAUC,UAAb,CAAyB,CACvBD,UAAUC,UAAV,CAAqB,GAAIC,KAAJ,CAAS,CAACP,OAAD,CAAT,CAAoB,CACvCQ,KAAMN,QADiC,CAApB,CAArB,CAEID,QAFJ,EAIF;AACC,CAND,IAMO,IAAIQ,KAAO,YAAcN,EAAzB,CAA4B,CACjCA,EAAE/G,IAAF,CAASqH,IAAIC,eAAJ,CAAoB,GAAIH,KAAJ,CAAS,CAACP,OAAD,CAAT,CAAoB,CAC/CQ,KAAMN,QADyC,CAApB,CAApB,CAAT,CAGAC,EAAEQ,YAAF,CAAe,UAAf,CAA2BV,QAA3B,EACAhG,SAASiB,IAAT,CAAc0F,WAAd,CAA0BT,CAA1B,EACAA,EAAEU,KAAF,GACA5G,SAASiB,IAAT,CAAc4F,WAAd,CAA0BX,CAA1B,CAED,CATM,IASA,CACL/H,OAAOiB,QAAP,CAAgBD,IAAhB,CAAuB,iCAAmC0G,mBAAmBE,OAAnB,CAA1D,CAAuF;AACxF,CACF,CAvBD","file":"utils.js","sourcesContent":["\nvar process = process || {};\nprocess.env = process.env || {};\n\nwindow.MEMLIKE = window.MEMLIKE || {};\nwindow.MEMLIKE.js_utils = {\n  build_date: "2026-04-30T09:18-04:00",\n};\n\n/* global $, window, document, console, navigator */\n/* global setTimeout, URL, Blob */\nvar GlobalEventEmitter = window.GlobalEventEmitter = {\n  _events: {},\n  dispatch: function (eventName, data) {\n      if (!this._events[eventName]) return;\n      for (var i = 0; i < this._events[eventName].length; i++)\n          this._events[eventName][i](data);\n  },\n  subscribe: function (eventName, callback) {\n    if (!this._events[eventName]) this._events[eventName] = [];\n    this._events[eventName].push(callback);\n  }\n}\n\n//+--------------------------------------------------------\n//| Get the value of a parameters of the given url (current location if false)\n//| Doesn't support array parameters\n//+--------------------------------------------------------\nvar getUrlParameters = window.getUrlParameters = function(href) {\n    if(typeof href == 'undefined' || href === false) {\n        href = window.location.href;\n    }\n    var hash = href.indexOf('#');\n    if(hash != -1) {\n        href = href.substr(0, hash);\n    }\n    var vars = {};\n    href.replace(\n        /[?&]+([^=&]+)=?([^&]*)?/gi, // regexp\n        function( m, key, value ) { // callback\n            vars[key] = value !== undefined ? value : '';\n        }\n    );\n    return vars;\n}\n\nvar getCookies = window.getCookies = function() {\n  let cookie = {};\n  document.cookie.split(';').forEach(function(el) {\n    let [k,v] = el.split('=');\n    cookie[k.trim()] = v;\n  })\n  return cookie;\n};\n\nvar objectsAreEqual = window.objectsAreEqual = function(newObj, oldObj){\n  if (Object.keys(oldObj).length !== Object.keys(newObj).length) {\n    return false;\n  }\n  for (const key in oldObj) {\n    if (typeof newObj[key] !== typeof newObj[key]) {\n      return false;\n    }\n    if (typeof newObj[key] === 'object') {\n      return objectsAreEqual(newObj[key], oldObj[key]);\n    }\n    if (oldObj[key] !== newObj[key]) {\n      return false;\n    }\n  }\n  return true;\n};\n\n//+--------------------------------------------------------\n//| Play/pause audio tag\n//+--------------------------------------------------------\nvar audioPlayer = window.audioPlayer = {\n  isInit: false,\n  target: false,\n  isPlaying: false,\n\n  reset: function() {\n\n    // Detect when audio has stopped playing\n    if(!audioPlayer.isInit) {\n      audioPlayer.isInit = true;\n\n       document.body.addEventListener('ended', function(e){\n        if(e.target == audioPlayer.target) {\n          audioPlayer.isPlaying = false;\n          audioPlayer.target.button.classList.remove('active');\n          audioPlayer.target = false;\n        }\n      }, true);\n    }\n\n    // Reset audioPlayer state\n    if(audioPlayer.isPlaying) {\n      audioPlayer.target.pause();\n      audioPlayer.target.button.classList.remove('active');\n    }\n    audioPlayer.target    = false;\n    audioPlayer.isPlaying = false;\n  },\n\n  init: function(){\n    audioPlayer.reset();\n\n    $('main').on('click', '.audio-player', audioPlayer.play);\n  },\n\n  // Play the target (this) audio element\n  // force: play the element even if it is already playing\n  play: function(e, force) {\n    if (e) {\n      e.preventDefault();\n      e.stopPropagation();\n    }\n    let audioBtn = this; // the .audio-player element (button/a)\n    let audioElement = this; // the audio element (if it exists)\n\n    if (audioBtn.nodeName == 'A' && audioBtn.classList.contains('url')) {\n      window.open(audioElement.getAttribute('src'), '_blank');\n      return;\n    }\n\n    if (audioBtn.dataset && 'id' in audioBtn.dataset) {\n      audioElement = document.getElementById(audioBtn.dataset.id);\n      if(!audioElement) {\n        console.error('Element with ID ' + audioBtn.dataset.id + ' doesnt exist');\n      }\n    }\n    if (audioElement.nodeName != 'AUDIO') {\n      console.error('Expected an audio element, instead of:', audioElement);\n      return;\n    }\n    audioElement.button = audioBtn;\n\n    // Toggle play/pause\n    if(audioPlayer.target === audioElement) {\n      if(force) {\n        if(!audioPlayer.isPlaying) {\n          audioElement.play();\n          audioPlayer.isPlaying = true;\n        }\n        return;\n      }\n      if(audioPlayer.isPlaying) {\n        audioElement.pause();\n        audioElement.button.classList.remove('active');\n      } else {\n        audioElement.play();\n        audioElement.button.classList.add('active');\n      }\n      audioPlayer.isPlaying = !audioPlayer.isPlaying;\n\n    // Pause any other player and play current target\n    } else {\n      if(audioPlayer.isPlaying) {\n        audioPlayer.target.pause();\n        audioPlayer.target.classList.remove('active');\n      }\n      audioElement.play();\n      audioElement.button.classList.add('active');\n      audioPlayer.target    = audioElement;\n      audioPlayer.isPlaying = true;\n    }\n  },\n\n  // Pause the current audio\n  pause: function() {\n    if(audioPlayer.isPlaying) {\n      audioPlayer.target.pause();\n      audioPlayer.target.button.classList.remove('active');\n      audioPlayer.isPlaying = false;\n    }\n  }\n};\n\n//+--------------------------------------------------------\n//| View image full size\n//+--------------------------------------------------------\nvar imgZoom = window.imgZoom = {\n  container: false,\n  n: 0,\n  i: 0,\n\n  reset: function() {\n    // for each images that have the text-image class: add the imgZoom attribute\n    imgZoom.n = $('main .text-image').each(function(i){\n      $(this).attr('id', 'imgZoom-' + i)\n             .data('i', i);\n    }).length;\n  },\n  init: function() {\n    imgZoom.reset();\n    $('main').on('click', '.text-image', imgZoom.open);\n  },\n  createContainer: function() {\n    var div = $('<div id=\"imgZoom\" style=\"display: none\">').appendTo(document.body);\n\n    // Backgroud=nd\n    $('<div class=\"backdrop\">')\n      .appendTo(div)\n      .on('click', imgZoom.close);\n\n    // Modal\n    $('<div class=\"modal\">')\n      .appendTo(div)\n\n      // Handle prev/next events\n      .on('click', '.slideshow-trigger', function(){\n        var i = ($(this).hasClass('prev') ? imgZoom.i - 1 : imgZoom.i + 1);\n        imgZoom.open.call(document.getElementById('imgZoom-' + i));\n      })\n      // Handle close btn\n      .on('click', '.modal-close-link', imgZoom.close);\n\n    imgZoom.container = div;\n  },\n  open: function() {\n    if(!imgZoom.container) {\n      imgZoom.createContainer();\n    }\n    var html = `<button type=\"button\" class=\"modal-close-link\">${window.I18N.close}</button>`;\n\n    // Img & legend\n    var legend = $(this).closest('.thing').find('.text').text();\n\n    html += `<figure>\n            <img class=\"zoom\" src=\"${this.getAttribute('src')}\">\n            ${legend ? `<figcaption>${legend}</figcaption>` : ''}\n          </figure>`;\n\n    // Prev & next\n    imgZoom.i = $(this).data('i');\n    if(imgZoom.i > 0) {\n      html += '<div class=\"slideshow-trigger prev\"></div>';\n    }\n    if(imgZoom.i + 1 < imgZoom.n) {\n      html += '<div class=\"slideshow-trigger next\"></div>';\n    }\n\n    // Render\n    $('.modal', imgZoom.container).html(html);\n    imgZoom.container.show();\n  },\n  close: function() {\n    imgZoom.container && imgZoom.container.hide();\n  }\n};\n\n//+--------------------------------------------------------\n//| Modal\n//+--------------------------------------------------------\nvar modal = window.modal = {\n  $container: false,\n  open_callback: {},\n  close_callback: {},\n\n  // Create the modal & itsbackdrop\n  createContainer: function () {\n    var div = $('<div id=\"modal\" style=\"display: none\">').appendTo(document.body);\n\n    // Background\n    $('<div class=\"backdrop\">').appendTo(div).on('click', modal.close);\n\n    // Modal\n    $('<div class=\"modal\">').appendTo(div);\n    modal.$container = div;\n  },\n\n  // Get the modal or create it\n  getContainer: function () {\n    if (!modal.$container) {\n      modal.createContainer();\n    }\n    return modal.$container;\n  },\n\n  // Set the content && open the modal\n  open: function (html) {\n    if (!modal.$container) {\n      modal.createContainer();\n    }\n    $('.modal', modal.$container).html(html);\n    modal.reopen();\n  },\n\n  // Open the modal && trigger all defined open-callbacks\n  reopen() {\n    modal.$container && modal.$container.show();\n\n    for (var k in modal.open_callback) {\n      modal.open_callback[k].call(modal, k);\n    }\n  },\n\n  // Close the modal && trigger all defined close-callbacks\n  close: function () {\n    modal.$container && modal.$container.hide();\n\n    for (var k in modal.close_callback) {\n      modal.close_callback[k].call(modal, k);\n    }\n  },\n\n  // Add/remove a named (k) callback, to call whenever a modal is opened\n  onOpen: function (k, callback) {\n    if (!callback) {\n      delete modal.open_callback[k];\n    } else if (typeof callback == 'function') {\n      modal.open_callback[k] = callback;\n    }\n  },\n  // Add/remove a named (k) callback, to call whenever a modal is opened\n  onClose: function (k, callback) {\n    if (!callback) {\n      delete modal.close_callback[k];\n    } else if (typeof callback == 'function') {\n      modal.close_callback[k] = callback;\n    }\n  },\n};\n\n//+--------------------------------------------------------\n//| Render markdown content\n//+--------------------------------------------------------\n\nvar defineMarkdown = window.defineMarkdown = function() {\n  if(window.markdown) {\n    window.markdown.decode = function(value) {\n      var STATIC_URL   = 'https://static.memrise.com/',\n          allowed_tags = 'p,strong,em,pre,code';\n\n      value = value.replace(/img:http:\\/\\/www.memrise.com\\/static\\//g, 'img:' + STATIC_URL)\n                   .replace(/img:http:\\/\\/memrise.com\\/static\\//g, 'img:' + STATIC_URL)\n                   .replace(/img:\\/static\\//g, 'img:' + STATIC_URL)\n                   .replace(/img:([^\\s<]+)/g, '`img:$1`');\n      value = window.markdown.toHTML(value);\n\n      var res = $('<div>').html(value);\n      res.find('*').each(function(){\n        $(this).is(allowed_tags) || $(this).remove();\n      });\n\n      value = res.html().trim()\n                .replace(/img:\\s*([^\\s<]+)/g, \"<img class='img-tag' src='$1' />\")\n                .replace(/embed:\\s*([^\\s<]+)/g, \"<a class='embed' href='$1' target='_blank'>$1</a>\");\n\n      // Header img + return carriage\n      value = value.replace(/<code>(<img class='img-tag' src='https:\\/\\/dummyimage.com\\/600x\\d+\\/([0-9A-Fa-f]{6}))/g, function(match, img, background){\n        return '<code style=\"background: #' + background + '\" class=\"header\">' + img;\n      })\n      .replace(/\\u2003+\\n/g, '<br>\\n');\n      return value;\n\n    };\n  } else {\n    window.markdown = {decode: function(value) { return value; }};\n  }\n}\n\nvar multimedia = window.multimedia = {\n  init: function() {\n    $('.multimedia-wrapper').each(function(){\n      var varname = this.getAttribute('data-var');\n\n      if(window[varname]) {\n        $(this).html(window.markdown.decode(window[varname]));\n      }\n      $(this).removeClass('loading-spinner');\n    });\n  }\n};\n\n//+--------------------------------------------------------\n//| Text To Speech\n//+--------------------------------------------------------\n\n// https://docs.cloud.google.com/translate/docs/languages?hl=de\nvar TTS = window.TTS = {\n  langs: {\n    'af': 'Afrikaans',\n    'sq': 'Albanian',\n    'am': 'Amharic',\n    'ar': 'Arabic',\n    'hy': 'Armenian',\n    'az': 'Azerbaijani',\n    'eu': 'Basque',\n    'be': 'Belarusian',\n    'bn': 'Bengali',\n    'bs': 'Bosnian',\n    'bg': 'Bulgarian',\n    'ca': 'Catalan',\n    'ceb': 'Cebuano',\n    'zh-CN': 'Chinese (Simplified)',\n    'zh-TW': 'Chinese (Traditional)',\n    'co': 'Corsican',\n    'hr': 'Croatian',\n    'cs': 'Czech',\n    'da': 'Danish',\n    'nl': 'Dutch',\n    'en': 'English',\n    'eo': 'Esperanto',\n    'et': 'Estonian',\n    'fi': 'Finnish',\n    'fr': 'French',\n    'fy': 'Frisian',\n    'gl': 'Galician',\n    'ka': 'Georgian',\n    'de': 'German',\n    'el': 'Greek',\n    'gu': 'Gujarati',\n    'ht': 'Haitian Creole',\n    'ha': 'Hausa',\n    'haw': 'Hawaiian',\n    'iw': 'Hebrew',\n    'hi': 'Hindi',\n    'hmn': 'Hmong',\n    'hu': 'Hungarian',\n    'is': 'Icelandic',\n    'ig': 'Igbo',\n    'id': 'Indonesian',\n    'ga': 'Irish',\n    'it': 'Italian',\n    'ja': 'Japanese',\n    'jw': 'Javanese',\n    'kn': 'Kannada',\n    'kk': 'Kazakh',\n    'km': 'Khmer',\n    'ko': 'Korean',\n    'ku': 'Kurdish',\n    'ky': 'Kyrgyz',\n    'lo': 'Lao',\n    'la': 'Latin',\n    'lv': 'Latvian',\n    'lt': 'Lithuanian',\n    'lb': 'Luxembourgish',\n    'mk': 'Macedonian',\n    'mg': 'Malagasy',\n    'ms': 'Malay',\n    'ml': 'Malayalam',\n    'mt': 'Maltese',\n    'mi': 'Maori',\n    'mr': 'Marathi',\n    'mn': 'Mongolian',\n    'my': 'Myanmar (Burmese)',\n    'ne': 'Nepali',\n    'no': 'Norwegian',\n    'ny': 'Nyanja (Chichewa)',\n    'ps': 'Pashto',\n    'fa': 'Persian',\n    'pl': 'Polish',\n    'pt': 'Portuguese (Portugal, Brazil)',\n    'pa': 'Punjabi',\n    'ro': 'Romanian',\n    'ru': 'Russian',\n    'sm': 'Samoan',\n    'gd': 'Scots Gaelic',\n    'sr': 'Serbian',\n    'st': 'Sesotho',\n    'sn': 'Shona',\n    'sd': 'Sindhi',\n    'si': 'Sinhala (Sinhalese)',\n    'sk': 'Slovak',\n    'sl': 'Slovenian',\n    'so': 'Somali',\n    'es': 'Spanish',\n    'su': 'Sundanese',\n    'sw': 'Swahili',\n    'sv': 'Swedish',\n    'tl': 'Tagalog (Filipino)',\n    'tg': 'Tajik',\n    'ta': 'Tamil',\n    'te': 'Telugu',\n    'th': 'Thai',\n    'tr': 'Turkish',\n    'uk': 'Ukrainian',\n    'ur': 'Urdu',\n    'uz': 'Uzbek',\n    'vi': 'Vietnamese',\n    'cy': 'Welsh',\n    'xh': 'Xhosa',\n    'yi': 'Yiddish',\n    'yo': 'Yoruba',\n    'zu': 'Zulu'\n  },\n  getAudioURL(text, lang) {\n    if(!TTS.langs[lang] || text.length >= 200) {\n      return;\n    }\n    const tk = Math.floor(Math.random() * 1000000);\n    const url = `https://translate.google.com/translate_tts?ie=UTF-8&tl=${lang}&client=tw-ob&q=${encodeURIComponent(text)}&tk=${tk}&ttsspeed=1`;\n    return 'https://cors-anywhere.99901dev.workers.dev/?q=' + encodeURIComponent(url);\n\n    // return 'https://google-tts-api.herokuapp.com/?q=' + encodeURIComponent(text) + '&tl=' + lang + '&ttspeed=1&download';\n  }\n};\n\n//+--------------------------------------------------------\n//| File download\n//+--------------------------------------------------------\n\n/**\n * Trigger a file download of the given mimeType\n * ex: download(csvContent, 'dowload.csv', 'text/csv;encoding:utf-8');\n *\n * @param string content\n * @param string fileName\n * @param mimeType\n */\nvar download = window.download = function(content, fileName, mimeType) {\n  var a = document.createElement('a');\n  mimeType = mimeType || 'application/octet-stream';\n\n  // IE10\n  if(navigator.msSaveBlob) {\n    navigator.msSaveBlob(new Blob([content], {\n      type: mimeType\n    }), fileName);\n\n  //html5 A[download]\n  } else if (URL && 'download' in a) {\n    a.href = URL.createObjectURL(new Blob([content], {\n      type: mimeType\n    }));\n    a.setAttribute('download', fileName);\n    document.body.appendChild(a);\n    a.click();\n    document.body.removeChild(a);\n\n  } else {\n    window.location.href = 'data:application/octet-stream,' + encodeURIComponent(content); // only this mime type is supported\n  }\n};\n"]}